<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Assessment;use Acorn\SafetyHealthcheck\Database\Schema;use Acorn\SafetyHealthcheck\Security\Honeypot;use RuntimeException;final class CompletionService{public function complete(string $token,array $p):array{global $wpdb;Honeypot::assertEmpty((string)($p['website']??''));$a=(new AssessmentRepository)->findByToken($token);if(!$a||$a['status']!=='assessed')throw new RuntimeException('Assessment must be assessed first.');foreach(['first_name','last_name','company','email']as$k)if(empty($p[$k]))throw new RuntimeException("Missing $k");if(!is_email($p['email']))throw new RuntimeException('Invalid work email.');$audit=($p['audit_requested']??false)?1:0;if($audit&&(!($p['telephone']??'')||!($p['postcode']??'')))throw new RuntimeException('Telephone and postcode are required.');$contact=(new ContactRepository)->create(['first_name'=>sanitize_text_field($p['first_name']),'last_name'=>sanitize_text_field($p['last_name']),'company'=>sanitize_text_field($p['company']),'email'=>sanitize_email($p['email']),'telephone'=>sanitize_text_field($p['telephone']??''),'postcode'=>sanitize_text_field($p['postcode']??''),'audit_requested'=>$audit,'marketing_consent'=>!empty($p['marketing_consent'])?1:0,'marketing_consent_at'=>!empty($p['marketing_consent'])?current_time('mysql'):null,'created_at'=>current_time('mysql')]);$raw=AssessmentRepository::token();$snapshot=(new SnapshotBuilder)->build((int)$a['id']);$wpdb->update(Schema::table('assessments'),['status'=>'completed','contact_id'=>$contact,'report_token_hash'=>hash('sha256',$raw),'snapshot_json'=>wp_json_encode($snapshot),'completed_at'=>current_time('mysql')],['id'=>$a['id']]);do_action('acorn_healthcheck_completed',(int)$a['id']);return['report_token'=>$raw,'assessment_id'=>(int)$a['id']];}}
